package com.adria.transaction.web.rest;import com.adria.transaction.domain.BankTransaction;import com.adria.transaction.service.TransactionService;import org.springframework.web.bind.annotation.*;import java.util.*;import java.math.*;
@RestController @RequestMapping("/api/transactions") public class TransactionRestController{private final TransactionService service;public TransactionRestController(TransactionService s){service=s;}public record CreateRequest(UUID accountId,BigDecimal amount,String currency,String merchantCategory,String country){}public record TransferRequest(UUID sourceAccountId,UUID destinationAccountId,BigDecimal amount){}
@PostMapping public BankTransaction create(@RequestBody CreateRequest r){return service.create(r.accountId(),r.amount(),r.currency(),r.merchantCategory(),r.country());}@GetMapping public List<BankTransaction> all(){return service.all();}@GetMapping("/{id}") public BankTransaction get(@PathVariable UUID id){return service.get(id);}@PostMapping("/transfer") public Map<String,Object> transfer(@RequestBody TransferRequest r){return service.transfer(r.sourceAccountId(),r.destinationAccountId(),r.amount());}}
